        w, k = q.popleft()
        if w == e:
            ans = k; break
        for i in range(len(w)):
            for c in "abcdefghijklmnopqrstuvwxyz":
                x = w[:i] + c + w[i + 1:]
                if x in words and x not in seen:
                    seen.add(x); q.append((x, k + 1))
    print(ans)

