        if k in c:
            c.move_to_end(k); out.append(c[k])
        else:
            out.append("-1")
    else:
        k, v = d[i + 1], d[i + 2]; i += 3
        c[k] = v; c.move_to_end(k)
        if len(c) > cap:
            c.popitem(last=False)
print("\n".join(out))

